local module = {}
local KeyMap = {}
local function GetKeyMap()
    if not next(KeyMap) then
        KeyMap = {
            [Enum.KeyCode.ButtonA.Name] = Enum.KeyCode.ButtonA,
            [Enum.KeyCode.ButtonB.Name] = Enum.KeyCode.ButtonB,
            [Enum.KeyCode.ButtonX.Name] = Enum.KeyCode.ButtonX,
            [Enum.KeyCode.ButtonY.Name] = Enum.KeyCode.ButtonY,
            [Enum.KeyCode.ButtonR1.Name] = Enum.KeyCode.ButtonR1,
            [Enum.KeyCode.ButtonL1.Name] = Enum.KeyCode.ButtonL1,
            [Enum.KeyCode.ButtonR2.Name] = Enum.KeyCode.ButtonR2,
            [Enum.KeyCode.ButtonL2.Name] = Enum.KeyCode.ButtonL2,
            [Enum.KeyCode.ButtonR3.Name] = Enum.KeyCode.ButtonR3,
            [Enum.KeyCode.ButtonL3.Name] = Enum.KeyCode.ButtonL3,
            [Enum.KeyCode.DPadLeft.Name] = Enum.KeyCode.DPadLeft,
            [Enum.KeyCode.DPadRight.Name] = Enum.KeyCode.DPadRight,
            [Enum.KeyCode.DPadUp.Name] = Enum.KeyCode.DPadUp,
            [Enum.KeyCode.DPadDown.Name] = Enum.KeyCode.DPadDown,
            [Enum.KeyCode.Thumbstick1.Name] = Enum.KeyCode.Thumbstick1,
            [Enum.KeyCode.Thumbstick2.Name] = Enum.KeyCode.Thumbstick2,
        }
    end
    return KeyMap
end
function module:GetAllKeyCodes()
    -- 返回一个包含所有游戏控制器按键的表
    return {
        Enum.KeyCode.ButtonA,
        Enum.KeyCode.ButtonB,
        Enum.KeyCode.ButtonX,
        Enum.KeyCode.ButtonY,
        Enum.KeyCode.ButtonR1,
        Enum.KeyCode.ButtonL1,
        Enum.KeyCode.ButtonR2,
        Enum.KeyCode.ButtonL2,
        Enum.KeyCode.ButtonR3,
        Enum.KeyCode.ButtonL3,
        Enum.KeyCode.DPadLeft,
        Enum.KeyCode.DPadRight,
        Enum.KeyCode.DPadUp,
        Enum.KeyCode.DPadDown,
        Enum.KeyCode.Thumbstick1,
        Enum.KeyCode.Thumbstick2,
    }
end

function module:GetKeyCodes(keys)
    local temp = {}
    local KeyMap = GetKeyMap()
    for i, v in pairs(keys) do
        local key = KeyMap[i]
        if key then
            table.insert(temp, key)
        end
    end
    return temp
end

return module